mapper.select:
select t.code,t.codename,t.sort,t.type1,t.type2,t.type3 from TBL_RISK_MONMODEL m 
 left join TBL_RISK_MONDICTONARY t on m.dictonaryid=t.id    
 left join TBL_MONMODEL_VERSION v on v.id=m.VERSIONID
 where 1=1

 and deptid=#{deptid}


 and versionId=#{versionId}

 and linkorgid=#{orgid}
 order by sort

select  code,M.DEPTID,o.ORGNAME as deptName   from TBL_RISK_MONDICTONARY r
 left join TBL_RISK_MONMODEL m on r.id= M.DICTONARYID
 left join TBL_ORGANIZATION  o on o.orgid=m.DEPTID
where r.orgid=#{orgid}

 and m.versionId=#{versionId}

order by sort

select code,M.DEPTID,o.ORGNAME as deptName from TBL_RISK_MONDICTONARY r left join TBL_RISK_MONMODEL m on r.id= M.DICTONARYID left join TBL_ORGANIZATION o on o.orgid=m.DEPTID where r.orgid=#{orgid}
and m.versionId=#{versionId}
and code2 in('AQBIGDECIMAL1','AQBIGDECIMAL3','AQBIGDECIMAL11','AQBIGDECIMAL7','CWBIGDECIMAL8','CWBIGDECIMAL12') order by sort
